// Initialize
// Helpers for PC and Mobile input handling
function isMobileDevice() {
    return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
}

function normalizeTime(val) {
    val = (val || '').trim();
    if (!val) return '';
    // Convert 845 or 0845 to 08:45
    if (/^\d{3,4}$/.test(val)) {
        if (val.length === 3) val = '0' + val;
        return val.substring(0, 2) + ':' + val.substring(2);
    }
    return val;
}

// Initialize
function init() {
    const isMobile = isMobileDevice();
    // 全てのデバイス（PC・スマホ）で時間入力を使いやすくするためにtextタイプとして扱い、自動整形を適用
    ['start-time', 'end-time'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.type = 'text';
            el.placeholder = 'HH:mm';
            el.setAttribute('inputmode', 'numeric'); // 数字キーボードを出しやすくする
            el.setAttribute('onfocus', 'this.select()');
            el.addEventListener('blur', function() {
                this.value = normalizeTime(this.value);
            });
        }
    });


    // Initialize Flatpickr for better styling control (like weekend colors)
    if (typeof flatpickr === "function" && datePicker) {
        const datePickerInstance = flatpickr(datePicker, {
        locale: "ja",
        defaultDate: currentDate,
        disableMobile: true, // Force consistent UI on mobile
        onChange: function (selectedDates, dateStr) {
            if (!persistCurrentDate(dateStr)) return;
            ensureDayRecords(currentDate);
            renderActiveDailyView();
            renderDailyNotes();
        },
        onDayCreate: function (dObj, dStr, fp, dayElem) {
            const dateStr = dayElem.dateObj.toLocaleDateString('sv-SE');
            // Sunday = 0, Saturday = 6, plus Holidays
            if (dayElem.dateObj.getDay() === 0 || isJapaneseHoliday(dayElem.dateObj)) {
                dayElem.classList.add("weekend-sun");
            } else if (dayElem.dateObj.getDay() === 6) {
                dayElem.classList.add("weekend-sat");
            }
        }
        });
        // Keep Flatpickr's internal selected date and the saved date in sync
        // after initialization, including Safari/iPhone reloads.
        datePickerInstance.setDate(currentDate, false);
    } else if (datePicker) {
        datePicker.addEventListener("change", function () {
            if (!persistCurrentDate(datePicker.value)) return;
            ensureDayRecords(currentDate);
            renderActiveDailyView();
            renderDailyNotes();
        });
        datePicker.value = currentDate;
    }
    // ensureDayRecords is now called inside Firebase listener after sync


    // Initialize Roll Stock Management BEFORE switching views to ensure data is loaded
    initRollStock();

    // Initialize Sliver Management
    initSliver();

    // Initialize Hanapon Management
    initHanapon();

    // Initialize Hanapon Box Inventory Management
    initHanaponBox();

    // Initialize Snow Sprint Management
    initSnowsprint();

    // Initialize Project Management
    initProjectManagement();

    // iPhone/Safari can suspend a page before a short inventory debounce finishes.
    // Flush only the pending calculation work whenever the page is about to pause.
    setupDeferredDataSyncLifecycle();

    // Check URL parameters or localStorage for view
    const urlParams = new URLSearchParams(window.location.search);
    const viewParam = urlParams.get('view') || getStoredView();
    if (viewParam && ['day', 'month', 'stock', 'sliver', 'hanapon', 'hanapon-box', 'snowsprint', 'shift', 'project', 'backup'].includes(viewParam)) {
        switchView(viewParam);
    } else {
        // Default to stock view if nothing is saved
        switchView('stock');
    }

    // Event Listeners
    viewDayBtn?.addEventListener('click', () => switchView('day'));
    viewMonthBtn?.addEventListener('click', () => switchView('month'));
    
    // Header Toggle Listeners (New)
    document.getElementById('view-day-btn')?.addEventListener('click', () => switchView('day'));
    document.getElementById('view-month-btn')?.addEventListener('click', () => switchView('month'));
    viewStockBtn?.addEventListener('click', () => switchView('stock'));
    viewSliverBtn?.addEventListener('click', () => switchView('sliver'));
    viewHanaponBtn?.addEventListener('click', () => switchView('hanapon'));
    viewHanaponBoxBtn?.addEventListener('click', () => switchView('hanapon-box'));
    viewSnowsprintBtn?.addEventListener('click', () => switchView('snowsprint'));
    viewShiftBtn?.addEventListener('click', () => switchView('shift'));

    document.getElementById('entry-form')?.addEventListener('submit', handleAddRecord);

    // Mobile Menu Setup
    setupMobileMenu();

}

let deferredDataSyncLifecycleBound = false;

function flushDeferredInventorySaves() {
    flushSliverPendingSave();
    flushHanaponPendingSave();
    flushSnowsprintPendingSave();
    flushHanaponBoxPendingSave();
}

function setupDeferredDataSyncLifecycle() {
    if (deferredDataSyncLifecycleBound) return;
    deferredDataSyncLifecycleBound = true;

    const flushBeforeSuspend = () => flushDeferredInventorySaves();
    window.addEventListener('pagehide', flushBeforeSuspend);
    window.addEventListener('freeze', flushBeforeSuspend);
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') flushBeforeSuspend();
    });
    window.addEventListener('online', flushBeforeSuspend);
    window.addEventListener('pageshow', flushBeforeSuspend);
}

function setupMobileMenu() {
    const sidebar = document.getElementById('sidebar');
    const sidebarOverlay = document.getElementById('sidebar-overlay');
    const hamburgerBtn = document.getElementById('hamburger-btn');
    const sidebarCloseBtn = document.getElementById('sidebar-close-btn');

    if (!hamburgerBtn || !sidebar || !sidebarOverlay) return;

    const toggleMenu = (show) => {
        sidebar.classList.toggle('open', show);
        sidebarOverlay.classList.toggle('active', show);
        if (show) {
            sidebarOverlay.style.display = 'block';
        } else {
            setTimeout(() => {
                if (!sidebar.classList.contains('open')) {
                    sidebarOverlay.style.display = 'none';
                }
            }, 300);
        }
    };

    hamburgerBtn.addEventListener('click', () => toggleMenu(true));
    sidebarCloseBtn?.addEventListener('click', () => toggleMenu(false));
    sidebarOverlay.addEventListener('click', () => toggleMenu(false));

    // Close menu when navigation item is clicked
    const navItems = sidebar.querySelectorAll('.nav-item');
    navItems.forEach(item => {
        item.addEventListener('click', () => toggleMenu(false));
    });
}

