function renderMonthlyRecords() {
    const currentMonth = currentDate.substring(0, 7); // YYYY-MM
    const monthRecords = records.filter(r => r.date.startsWith(currentMonth));

    // Monthly Summary By Product
    const productTotals = {};
    const dailyData = {};
    let totalMonthCount = 0;

    monthRecords.forEach(r => {
        if (r.count > 0 || r.product !== '') {
            const p = r.product.trim() || '(未入力)';
            productTotals[p] = (productTotals[p] || 0) + r.count;
            totalMonthCount += r.count;

            if (!dailyData[r.date]) {
                dailyData[r.date] = { total: 0, no6: 0, hanaponS: 0, machines: new Set() };
            }
            dailyData[r.date].total += r.count;
            if (p === 'No.6') dailyData[r.date].no6 += r.count;
            if (p === '鼻ぽん小') dailyData[r.date].hanaponS += r.count;
            if (r.count > 0) dailyData[r.date].machines.add(r.machine);
        }
    });

    // Render Product Totals
    const productListEl = document.getElementById('monthly-product-totals');
    productListEl.innerHTML = Object.entries(productTotals).sort((a, b) => b[1] - a[1]).map(([name, count]) => `
        <div style="display: flex; justify-content: space-between; padding: 0.5rem 0; border-bottom: 1px solid var(--border);">
            <span style="font-weight: 600;">${name}</span>
            <span style="font-weight: 800; color: var(--primary);">${count.toLocaleString()}</span>
        </div>
    `).join('') || '<p style="color:var(--text-muted)">データがありません</p>';

    // Render Full Detailed Monthly List
    const fullDetailedListEl = document.getElementById('monthly-full-detailed-list');
    const sortedRecords = monthRecords
        .filter(r => r.count > 0 || r.product !== '')
        .sort((a, b) => b.date.localeCompare(a.date) || a.machine.localeCompare(b.machine));

    let html = '';
    let lastDate = '';

    sortedRecords.forEach(r => {
        // Add date divider if date changes
        if (r.date !== lastDate) {
            html += `
                <tr class="date-group-divider">
                    <td colspan="6" style="padding: 1rem;">
                        ${r.date.split('-')[0]}年 ${r.date.split('-')[1]}月 ${r.date.split('-')[2]}日
                    </td>
                </tr>
            `;
            lastDate = r.date;
        }

        html += `
            <tr>
                <td style="color: var(--text-muted); font-size: 0.85rem;">${r.date.split('-')[1]}/${r.date.split('-')[2]}</td>
                <td class="machine-cell"><span class="machine-badge">${r.machine}</span></td>
                <td class="product-cell" style="font-weight: 600;">${r.product || '-'}</td>
                <td class="time-cell">${r.startTime}</td>
                <td class="time-cell">${r.endTime}</td>
                <td style="text-align: right; font-weight: 700; color: var(--primary);">
                    ${r.count.toLocaleString()}
                </td>
            </tr>
        `;
    });

    fullDetailedListEl.innerHTML = html || '<tr><td colspan="6" style="text-align:center; padding: 2rem;">記録がありません</td></tr>';
}

// Handle Quick Entry
function handleAddRecord(e) {
    e.preventDefault();
    if (!canWriteAppData()) return;

    const startTimeInput = document.getElementById('start-time');
    const endTimeInput = document.getElementById('end-time');

    startTimeInput.value = normalizeTime(startTimeInput.value);
    endTimeInput.value = normalizeTime(endTimeInput.value);


    const record = {
        id: Date.now() + Math.random(),
        date: currentDate,
        machine: document.getElementById('machine').value,
        product: document.getElementById('product').value,
        startTime: startTimeInput.value,
        endTime: endTimeInput.value,
        count: parseInt(document.getElementById('count').value || 0),
        orderCount: 0,
        [DAILY_RECORD_UPDATED_AT_FIELD]: Date.now()
    };

    records.push(record);
    saveRecords();
    renderRecords();

    // Partially reset form
    document.getElementById('product').value = '';
    document.getElementById('count').value = '';
}

// Daily Notes Data Logic
function renderDailyNotes() {
    const textarea = document.getElementById('day-note-text');
    if (textarea) {
        textarea.value = dailyNotes[currentDate] || "";
    }
}

function syncDailyNotesNow() {
    noteSaveTimeout = null;
    if (dailyNotesSync) dailyNotesSync.save(dailyNotes);
    const saveStatus = document.getElementById('saveStatusNotes');
    if (saveStatus) {
        saveStatus.textContent = "\u4fdd\u5b58\u3057\u307e\u3057\u305f";
        setTimeout(() => saveStatus.textContent = "", 3000);
    }
}

// Global function to be called on textarea input
window.saveDailyNotes = function() {
    if (!canWriteAppData()) return;
    const textarea = document.getElementById('day-note-text');
    if (!textarea) return;
    
    const text = textarea.value.trim();
    if (text) {
        dailyNotes[currentDate] = text;
    } else {
        delete dailyNotes[currentDate];
    }
    
    // Save to local storage immediately
    localStorage.setItem(NOTES_LS_KEY, JSON.stringify(dailyNotes));
                scheduleDailyBackupRefresh();
    triggerHistorySave();
    
    // SharedSync stores the pending change first, so an immediate save also
    // survives Safari suspending the page before the user leaves the field.
    clearTimeout(noteSaveTimeout);
    syncDailyNotesNow();
}

// Japanese Holiday Calculation
function isJapaneseHoliday(dateStr) {
    if (!dateStr) return false;
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return false;

    const y = date.getFullYear();
    const m = date.getMonth() + 1;
    const d = date.getDate();
    const w = date.getDay(); // 0:Sun, 1:Mon...

    // 1. Fixed Holidays
    if (isFixedHoliday(y, m, d)) return true;

    // 2. Happy Monday Holidays
    const nthMonday = Math.floor((d - 1) / 7) + 1;
    if (w === 1) {
        if (m === 1 && nthMonday === 2) return true; // 成人の日 (2nd Mon)
        if (m === 7 && nthMonday === 3) return true; // 海の日 (3rd Mon)
        if (m === 9 && nthMonday === 3) return true; // 敬老の日 (3rd Mon)
        if (m === 10 && nthMonday === 2) return true; // スポーツの日 (2nd Mon)
    }

    // 3. Substitute Holidays (振替休日)
    // Simplified check: If Monday, and yesterday (Sunday) was a fixed holiday
    if (w === 1) {
        const yesterday = new Date(y, m - 1, d - 1);
        if (isFixedHoliday(yesterday.getFullYear(), yesterday.getMonth() + 1, yesterday.getDate())) return true;

        // Special case for GW: if 5/3-5/5 were Sunday or already compensated...
        // For simplicity, checking if 5/6 is Monday and any of 5/3, 5/4, 5/5 was Sunday
        if (m === 5 && d === 6) {
            const d3 = new Date(y, 4, 3).getDay();
            const d4 = new Date(y, 4, 4).getDay();
            const d5 = new Date(y, 4, 5).getDay();
            if (d3 === 0 || d4 === 0 || d5 === 0) return true;
        }
    }

    // 4. National Holidays (国民の休日 - Bridge holidays)
    // Sandwiched between two holidays.
    const pStr = `${y}-${String(m).padStart(2, '0')}-${String(d - 1).padStart(2, '0')}`;
    const nStr = `${y}-${String(m).padStart(2, '0')}-${String(d + 1).padStart(2, '0')}`;
    // Use isFixedHoliday for simplified bridge check
    if (isFixedHoliday(y, m, d - 1) && isFixedHoliday(y, m, d + 1)) return true;

    return false;
}

// Fixed Holidays (and Equinoxes)
function isFixedHoliday(y, m, d) {
    if (m === 1 && d === 1) return true; // 元日
    if (m === 2 && d === 11) return true; // 建国記念の日
    if (m === 2 && d === 23) return true; // 天皇誕生日
    if (m === 4 && d === 29) return true; // 昭和の日
    if (m === 5 && d === 3) return true; // 憲法記念日
    if (m === 5 && d === 4) return true; // みどりの日
    if (m === 5 && d === 5) return true; // こどもの日
    if (m === 8 && d === 11) return true; // 山の日
    if (m === 11 && d === 3) return true; // 文化の日
    if (m === 11 && d === 23) return true; // 勤労感謝の日

    // Equinoxes
    let vernal = Math.floor(20.8431 + 0.242194 * (y - 1980) - Math.floor((y - 1980) / 4));
    if (m === 3 && d === vernal) return true;
    let autumnal = Math.floor(23.2488 + 0.242194 * (y - 1980) - Math.floor((y - 1980) / 4));
    if (m === 9 && d === autumnal) return true;

    return false;
}

// Ensure machines A-J exist for a specific date
function ensureDayRecords(date) {
    if (!canWriteAppData()) return;

    // Skip if weekend (Saturday=6, Sunday=0) or Holiday
    const dayOfWeek = new Date(date).getDay();
    if (dayOfWeek === 0 || dayOfWeek === 6 || isJapaneseHoliday(date)) return;

    const existingMachines = records.filter(r => r.date === date).map(r => r.machine);
    let updated = false;

    // Find previous records sorted by date descending
    const previousRecords = records.filter(r => r.date < date).sort((a, b) => b.date.localeCompare(a.date));

    MACHINES.forEach(m => {
        if (!existingMachines.includes(m)) {
            // Find the last record for this machine that had a product name set
            const lastRecordWithProduct = previousRecords.find(r => r.machine === m && r.product !== '');
            const lastProduct = lastRecordWithProduct ? lastRecordWithProduct.product : '';

            records.push({
                id: Date.now() + Math.random(),
                date: date,
                machine: m,
                product: lastProduct,
                startTime: '08:45',
                endTime: '16:30',
                count: 0,
                orderCount: 0,
                [DAILY_RECORD_UPDATED_AT_FIELD]: Date.now()
            });
            updated = true;
        }
    });

    if (updated) saveRecords(false); // 自動追加時は履歴を作動させない
}

// Update a specific field in a record
function updateRecord(id, field, value, options = {}) {
    if (!canWriteAppData()) return;

    const record = records.find(r => r.id == id);
    if (!record) return;

    if (field === 'count' || field === 'orderCount') {
        record[field] = parseInt(value) || 0;
    } else {
        record[field] = value;
    }

    // If product name is changed, propagate this choice to future dates that haven't been "started" yet
    const updatedAt = Date.now();
    record[DAILY_RECORD_UPDATED_AT_FIELD] = updatedAt;

    if (field === 'product' && options.propagateProduct !== false) {
        const realToday = new Date().toLocaleDateString('sv-SE');
        // Propagation only happens if we are editing today's or a future record
        if (record.date >= realToday) {
            records.forEach(futureRecord => {
                if (futureRecord.date > record.date &&
                    futureRecord.machine === record.machine &&
                    futureRecord.count === 0) {
                    futureRecord.product = value;
                    futureRecord[DAILY_RECORD_UPDATED_AT_FIELD] = updatedAt;
                }
            });
        }
    }

    saveRecords();
    calculateAndDisplayStats();
}

function updateRecordLive(id, field, value) {
    updateRecord(id, field, value, { propagateProduct: false });
}

// Calculate Duration
function calculateDuration(start, end) {
    if (!start || !end) return { h: 0, m: 0, totalMinutes: 0 };
    const s = start.split(':').map(Number);
    const e = end.split(':').map(Number);
    let diff = (e[0] * 60 + e[1]) - (s[0] * 60 + s[1]);
    if (diff < 0) diff += 24 * 60;

    const h = Math.floor(diff / 60);
    const m = diff % 60;
    return { h, m, totalMinutes: diff };
}

// Save to LocalStorage and Firebase (with enhanced reliability)
function saveRecords(triggerHistory = true) {
    if (!canWriteAppData()) return false;

    try {
        records = normalizeDailyRecords(records);
        localStorage.setItem(LS_KEY, JSON.stringify(records));
        scheduleDailyBackupRefresh();
        if (triggerHistory) triggerHistorySave();
    } catch (e) {
        console.error('LocalStorage save failed:', e);
    }

    if (database) {
        if (Array.isArray(records) && records.length === 0) {
            console.warn('BLOCKED: Attempted to save empty records array to Firebase');
            return;
        }
        queueRecordsSync();
    }
}

// Google Sheets Synchronization
async function syncToGoogleSheets(recordsToSync) {
    const GAS_URL = 'https://script.google.com/macros/s/AKfycbxU3MdLFS_1LxJ1T1dFpt0QVN2PejD3QBnSHxaVfN9edGjNuRU6IJkmg9csfRtlvzba/exec';

    // Only send data that has content
    const activeRecords = recordsToSync.filter(r => r.count > 0 || (r.product && r.product !== ''));

    if (activeRecords.length === 0) return;

    try {
        await fetch(GAS_URL, {
            method: 'POST',
            mode: 'no-cors', // Important for GAS
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                floor: '2F',
                records: activeRecords
            }),
        });
        console.log('Synced to Google Sheets (2F)');
    } catch (e) {
        console.error('Google Sheets sync failed:', e);
    }
}

// Google Sheets Synchronization for Roll Stock
async function syncRollToGoogleSheets(year, month) {
    const GAS_URL = 'https://script.google.com/macros/s/AKfycbzOetoYvk0WkzIa9LsgcODc5qfnsUJbyT_PZVSfZLWxQPaA0x9V2T7OLQqfM3w5zShP/exec';

    const key = `${year}-${month}`;
    const data = rollAllData[key];
    if (!data) return;

    const daysInMonth = new Date(year, month, 0).getDate();
    const records = [];

    // 1. Add Carryover Row (Matches UI top row)
    const carryRow = {
        date: "繰越分",
        filmDel: "", filmProd: "", filmRem: data.film.carryover || 0,
        plainDel: "", plainProd: "", plainRem: data.plain.carryover || 0,
        plain2Del: "", plain2Prod: "", plain2Rem: data.plain2.carryover || 0,
        eogDel: "", eogProd: "", eogRem: data.eog.carryover || 0
    };
    records.push(carryRow);

    // 2. Calculate daily balances and add ALL days (even if 0) to match the table exactly
    const currentBalances = {};
    ROLL_TYPES.forEach(type => {
        currentBalances[type] = data[type].carryover || 0;
    });

    for (let d = 1; d <= daysInMonth; d++) {
        const dateObj = new Date(year, month - 1, d);
        const dayOfWeek = ROLL_DAY_NAMES[dateObj.getDay()];
        const row = {
            date: `${year}/${month}/${d} (${dayOfWeek})`,
        };

        ROLL_TYPES.forEach(type => {
            const dData = (data[type].days && data[type].days[d]) || {};
            const del = dData.delivery || 0;
            const prod = dData.production || 0;
            currentBalances[type] = currentBalances[type] + del - prod;

            row[`${type}Del`] = del || ""; // Use empty string for 0 to keep it clean
            row[`${type}Prod`] = prod || "";
            row[`${type}Rem`] = currentBalances[type];
        });

        records.push(row);
    }

    try {
        await fetch(GAS_URL, {
            method: 'POST',
            mode: 'no-cors',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                floor: 'ロール在庫表',
                year: year,
                month: month,
                records: records
            }),
        });
        console.log(`Synced Roll Stock for ${year}/${month} to Google Sheets`);
    } catch (e) {
        console.error('Roll Stock Google Sheets sync failed:', e);
    }
}

