// Helper to update duration text immediately after time change
window.getDurationLabel = (id, newStart, newEnd) => {
    const record = records.find(r => r.id == id);
    const start = newStart || record.startTime;
    const end = newEnd || record.endTime;
    const { h, m } = calculateDuration(start, end);
    return `${h}時間 ${m}分`;
};

function calculateAndDisplayStats() {
    const dayRecords = records.filter(r => r.date === currentDate);
    let totalCount = 0;
    let totalNo6 = 0;
    let totalHanaponSmall = 0;
    let totalHanaponLarge = 0;
    let totalMinutes = 0;
    let activeEntries = 0;

    dayRecords.forEach(r => {
        if (r.count > 0 || r.product !== '') {
            totalCount += r.count;

            // Specific product totals
            const p = r.product.trim();
            if (p === 'No.6') totalNo6 += r.count;
            if (p === '鼻ぽん小') totalHanaponSmall += r.count;
            if (p === '鼻ぽん大') totalHanaponLarge += r.count;

            const { totalMinutes: mins } = calculateDuration(r.startTime, r.endTime);
            totalMinutes += mins;
            activeEntries++;
        }
    });

    if (dayTotalEl) dayTotalEl.textContent = totalCount.toLocaleString();
    const no6TotalEl = document.getElementById('no6-total-count');
    if (no6TotalEl) no6TotalEl.textContent = totalNo6.toLocaleString();
    const hanaponTotalEl = document.getElementById('hanapon-s-total-count');
    if (hanaponTotalEl) hanaponTotalEl.textContent = totalHanaponSmall.toLocaleString();
    const hanaponLTotalEl = document.getElementById('hanapon-l-total-count');
    if (hanaponLTotalEl) hanaponLTotalEl.textContent = totalHanaponLarge.toLocaleString();

    if (avgDurationEl) {
        if (activeEntries > 0) {
            const avgMins = totalMinutes / activeEntries;
            const h = Math.floor(avgMins / 60);
            const m = Math.floor(avgMins % 60);
            avgDurationEl.textContent = `${h}h ${m.toString().padStart(2, '0')}m`;
        } else {
            avgDurationEl.textContent = '0h 00m';
        }
    }
}

// Reset a row
function clearRow(id) {
    if (!canWriteAppData()) return;

    const record = records.find(r => r.id == id);
    if (!record) return;
    record.product = '';
    record.count = 0;
    record[DAILY_RECORD_UPDATED_AT_FIELD] = Date.now();
    saveRecords();
    renderRecords();
}

// Delete a row
function deleteRecord(id) {
    if (!canWriteAppData()) return;

    if (confirm('この項目を削除してもよろしいですか？')) {
        records = records.filter(r => r.id != id);
        saveRecords();
        renderRecords();
    }
}


