function initSliver() {
    // Load from localStorage or use initial data
    const stored = localStorage.getItem(SLIVER_STORAGE_KEY);
    if (stored) {
        try {
            sliverAllData = JSON.parse(stored);
        } catch (e) {
            sliverAllData = JSON.parse(JSON.stringify(SLIVER_INITIAL_DATA));
        }
    } else {
        sliverAllData = JSON.parse(JSON.stringify(SLIVER_INITIAL_DATA));
        localStorage.setItem(SLIVER_STORAGE_KEY, JSON.stringify(sliverAllData));
                scheduleDailyBackupRefresh();
    }

    // Ensure current month exists
    ensureSliverMonth(sliverCurrentYear, sliverCurrentMonth, false);

    // Setup month selector
    setupSliverMonthSelector();

    if (database && window.SharedSync && !sliverDataSync) {
        sliverDataSync = SharedSync.createPathSync({
            database,
            path: SLIVER_DB_PATH,
            emptyValue: {},
            pendingStorageKey: SLIVER_STORAGE_KEY + '_pending_sync',
            serverSnapshotStorageKey: SLIVER_STORAGE_KEY + '_server_snapshot',
            getLocal: () => sliverAllData,
            setLocal: value => {
                sliverAllData = value;
                localStorage.setItem(SLIVER_STORAGE_KEY, JSON.stringify(sliverAllData));
                scheduleDailyBackupRefresh();
            },
            onRemote: () => {
                const activeEl = document.activeElement;
                ensureSliverMonth(sliverCurrentYear, sliverCurrentMonth, true);
                if (!activeEl?.closest('#sliver-view-container')
                    && sliverViewContainer.style.display === 'block') renderSliver();
            }
        });
    }
}

function ensureSliverMonth(year, month, shouldSave = true) {
    const key = `${year}-${month}`;
    if (!sliverAllData[key]) {
        // Try to calculate carryover from previous month
        const prevMonth = month === 1 ? 12 : month - 1;
        const prevYear = month === 1 ? year - 1 : year;
        const prevKey = `${prevYear}-${prevMonth}`;
        const prevData = sliverAllData[prevKey];

        const newMonth = { p: {}, m: {} };

        ['p', 'm'].forEach(section => {
            const types = section === 'p' ? SLIVER_P_TYPES : SLIVER_M_TYPES;
            types.forEach(t => {
                let carry = 0;
                if (prevData && prevData[section] && prevData[section][t.key]) {
                    carry = calculateSliverEndBalance(prevData[section][t.key], prevYear, prevMonth);
                }
                newMonth[section][t.key] = {
                    name: t.name,
                    carryover: carry,
                    days: {}
                };
            });
        });

        sliverAllData[key] = newMonth;
        if (shouldSave) saveSliverData(false); // 自動作成時は履歴を作動させない
    }
}

function calculateSliverEndBalance(typeData, year, month) {
    let balance = typeData.carryover || 0;
    const daysInMonth = new Date(year, month, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
        const dData = (typeData.days && typeData.days[d]) || {};
        balance = balance + (dData.incoming || 0) - (dData.morning || 0) - (dData.evening || 0);
    }
    return balance;
}

function setupSliverMonthSelector() {
    const yearSelect = document.getElementById('yearSelectSliver');
    const monthSelect = document.getElementById('monthSelectSliver');
    const prevBtn = document.getElementById('prevMonthSliver');
    const nextBtn = document.getElementById('nextMonthSliver');

    if (!yearSelect || !monthSelect) return;

    // Populate year options
    yearSelect.innerHTML = '';
    for (let y = 2025; y <= 2100; y++) {
        const opt = document.createElement('option');
        opt.value = y;
        opt.textContent = y;
        if (y === sliverCurrentYear) opt.selected = true;
        yearSelect.appendChild(opt);
    }

    // Populate month options
    monthSelect.innerHTML = '';
    for (let m = 1; m <= 12; m++) {
        const opt = document.createElement('option');
        opt.value = m;
        opt.textContent = m;
        if (m === sliverCurrentMonth) opt.selected = true;
        monthSelect.appendChild(opt);
    }

    yearSelect.addEventListener('change', () => {
        sliverCurrentYear = parseInt(yearSelect.value);
        ensureSliverMonth(sliverCurrentYear, sliverCurrentMonth);
        renderSliver();
    });

    monthSelect.addEventListener('change', () => {
        sliverCurrentMonth = parseInt(monthSelect.value);
        ensureSliverMonth(sliverCurrentYear, sliverCurrentMonth);
        renderSliver();
    });

    prevBtn?.addEventListener('click', () => {
        sliverCurrentMonth--;
        if (sliverCurrentMonth < 1) { sliverCurrentMonth = 12; sliverCurrentYear--; }
        yearSelect.value = sliverCurrentYear;
        monthSelect.value = sliverCurrentMonth;
        ensureSliverMonth(sliverCurrentYear, sliverCurrentMonth);
        renderSliver();
    });

    nextBtn?.addEventListener('click', () => {
        sliverCurrentMonth++;
        if (sliverCurrentMonth > 12) { sliverCurrentMonth = 1; sliverCurrentYear++; }
        yearSelect.value = sliverCurrentYear;
        monthSelect.value = sliverCurrentMonth;
        ensureSliverMonth(sliverCurrentYear, sliverCurrentMonth);
        renderSliver();
    });
}

function saveSliverData(triggerHistory = true) {
    if (!canWriteAppData()) return false;

    try {
        localStorage.setItem(SLIVER_STORAGE_KEY, JSON.stringify(sliverAllData));
                scheduleDailyBackupRefresh();
        if (triggerHistory) triggerHistorySave();
    } catch (e) {
        console.error('Sliver localStorage save failed:', e);
    }

    if (database) {
        // 空データ保護
        if (Object.keys(sliverAllData).length === 0) {
            console.warn('BLOCKED: Attempted to save empty sliverAllData to Firebase');
            return;
        }
        if (sliverDataSync) sliverDataSync.save(sliverAllData);
    }
}

function renderSliver() {
    const key = `${sliverCurrentYear}-${sliverCurrentMonth}`;
    const data = sliverAllData[key];
    if (!data) return;

    renderSliverSection('P', data.p, SLIVER_P_TYPES);
    renderSliverSection('M', data.m, SLIVER_M_TYPES);
}

function renderSliverSection(section, sectionData, typesDef) {
    const thead = document.getElementById(`sliverHead${section}`);
    const tbody = document.getElementById(`sliverBody${section}`);
    const tfoot = document.getElementById(`sliverFoot${section}`);
    if (!thead || !tbody || !tfoot) return;

    const daysInMonth = new Date(sliverCurrentYear, sliverCurrentMonth, 0).getDate();
    const today = new Date().toLocaleDateString('sv-SE');

    // Build header
    let headerMain = '<tr><th rowspan="2" class="sliver-date-col">出庫日</th>';
    let headerSub = '<tr>';

    typesDef.forEach((t, i) => {
        headerMain += `<th colspan="4" class="sliver-group-${i}">${t.name}</th>`;
        headerSub += `<th class="sliver-sub-${i}"><span class="sliver-text-desktop">入庫</span><span class="sliver-text-mobile">入</span></th>`;
        headerSub += `<th class="sliver-sub-${i}"><span class="sliver-text-desktop">朝出庫</span><span class="sliver-text-mobile">朝</span></th>`;
        headerSub += `<th class="sliver-sub-${i}"><span class="sliver-text-desktop">夕出庫</span><span class="sliver-text-mobile">夕</span></th>`;
        headerSub += `<th class="sliver-sub-${i}"><span class="sliver-text-desktop">出庫後</span><span class="sliver-text-mobile">残</span></th>`;
    });

    headerMain += '</tr>';
    headerSub += '</tr>';
    thead.innerHTML = headerMain + headerSub;

    // Build carryover row
    let carryHtml = `<tr style="background: rgba(var(--primary-rgb), 0.03);"><td class="sliver-date-col" style="font-weight:700; padding:0.5rem; white-space:nowrap; border: 1px solid var(--border);">
        <span class="carryover-text-desktop">前月繰越</span>
        <span class="carryover-text-mobile">繰越</span>
    </td>`;
    typesDef.forEach((t, i) => {
        const carry = (sectionData[t.key] && sectionData[t.key].carryover) || 0;
        carryHtml += `<td colspan="3"></td>`;
        carryHtml += `<td class="sliver-remaining" style="font-weight:800; color:var(--primary);">${carry}</td>`;
    });
    carryHtml += '</tr>';

    // Build daily rows
    let rowsHtml = carryHtml;
    const balances = {};
    typesDef.forEach(t => {
        balances[t.key] = (sectionData[t.key] && sectionData[t.key].carryover) || 0;
    });

    for (let d = 1; d <= daysInMonth; d++) {
        const dateObj = new Date(sliverCurrentYear, sliverCurrentMonth - 1, d);
        const dayOfWeek = dateObj.getDay();
        const dayName = SLIVER_DAY_NAMES[dayOfWeek];
        const dateStr = `${sliverCurrentYear}-${String(sliverCurrentMonth).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const isToday = dateStr === today;
        const isSunday = dayOfWeek === 0;
        const isSaturday = dayOfWeek === 6;
        const isHoliday = isJapaneseHoliday(dateStr);

        let rowClass = '';
        if (isToday) rowClass = 'sliver-row-today';
        else if (isSunday) rowClass = 'sliver-row-sunday';
        else if (isSaturday) rowClass = 'sliver-row-saturday';
        else if (isHoliday) rowClass = 'sliver-row-holiday';

        let dateLabel = `${sliverCurrentMonth}/${d}(${dayName})`;

        rowsHtml += `<tr class="${rowClass}">`;
        rowsHtml += `<td class="sliver-date-col" style="font-size:0.8rem; padding:0.4rem; white-space:nowrap;">${dateLabel}</td>`;

        typesDef.forEach((t, i) => {
            const dData = (sectionData[t.key] && sectionData[t.key].days && sectionData[t.key].days[d]) || {};
            const incoming = dData.incoming || 0;
            const morning = dData.morning || 0;
            const evening = dData.evening || 0;

            balances[t.key] = balances[t.key] + incoming - morning - evening;
            const rem = balances[t.key];

            const sectionKey = section.toLowerCase();

            // 入庫
            rowsHtml += `<td><input type="number" class="sliver-input" value="${incoming || ''}" 
                data-section="${sectionKey}" data-type="${t.key}" data-day="${d}" data-field="incoming"
                oninput="updateSliverCell(this)" onblur="flushSliverPendingSave()" onfocus="this.select()"></td>`;
            // 朝出庫
            rowsHtml += `<td><input type="number" class="sliver-input" value="${morning || ''}" 
                data-section="${sectionKey}" data-type="${t.key}" data-day="${d}" data-field="morning"
                oninput="updateSliverCell(this)" onblur="flushSliverPendingSave()" onfocus="this.select()"></td>`;
            // 夕出庫
            rowsHtml += `<td><input type="number" class="sliver-input" value="${evening || ''}" 
                data-section="${sectionKey}" data-type="${t.key}" data-day="${d}" data-field="evening"
                oninput="updateSliverCell(this)" onblur="flushSliverPendingSave()" onfocus="this.select()"></td>`;
            // 出庫後 (calculated)
            const lowClass = rem <= 5 ? ' low-stock' : '';
            rowsHtml += `<td class="sliver-remaining${lowClass}" id="sliver-rem-${sectionKey}-${t.key}-${d}">${rem}</td>`;
        });

        rowsHtml += '</tr>';
    }

    tbody.innerHTML = rowsHtml;

    // Footer - monthly totals
    let footHtml = '<tr style="background: var(--bg-main); border-top: 2px solid var(--border);">';
    footHtml += '<td class="sliver-date-col" style="font-weight:700; padding:0.75rem; white-space:nowrap;">残数</td>';

    typesDef.forEach((t, i) => {
        let totalIn = 0, totalMorn = 0, totalEve = 0;
        for (let d = 1; d <= daysInMonth; d++) {
            const dData = (sectionData[t.key] && sectionData[t.key].days && sectionData[t.key].days[d]) || {};
            totalIn += (dData.incoming || 0);
            totalMorn += (dData.morning || 0);
            totalEve += (dData.evening || 0);
        }
        const finalRem = balances[t.key];
        footHtml += `<td style="font-weight:700">${totalIn || ''}</td>`;
        footHtml += `<td style="font-weight:700">${totalMorn || ''}</td>`;
        footHtml += `<td style="font-weight:700">${totalEve || ''}</td>`;
        footHtml += `<td style="font-weight:800; color:var(--primary)">${finalRem}</td>`;
    });

    footHtml += '</tr>';
    tfoot.innerHTML = footHtml;
}

function updateSliverCell(input) {
    sliverLastEditTime = Date.now();
    const section = input.dataset.section; // 'p' or 'm'
    const typeKey = input.dataset.type;
    const day = input.dataset.day;
    const field = input.dataset.field;
    let value = input.value.trim();
    value = value === '' ? 0 : parseInt(value);
    if (isNaN(value)) return;

    const key = `${sliverCurrentYear}-${sliverCurrentMonth}`;
    if (!sliverAllData[key]) return;
    if (!sliverAllData[key][section]) return;
    if (!sliverAllData[key][section][typeKey]) return;

    const dataObj = sliverAllData[key][section][typeKey];

    if (!dataObj.days) {
        dataObj.days = {};
    }
    if (!dataObj.days[day]) {
        dataObj.days[day] = {};
    }

    if (value === 0) {
        delete dataObj.days[day][field];
    } else {
        dataObj.days[day][field] = value;
    }

    // Clean up empty days
    if (Object.keys(dataObj.days[day]).length === 0) {
        delete dataObj.days[day];
    }

    // Recalculate remaining balances for this section (for current month visualization)
    recalculateSliverSection(section);

    // Save to local storage immediately for fast local reflection
    localStorage.setItem(SLIVER_STORAGE_KEY, JSON.stringify(sliverAllData));
                scheduleDailyBackupRefresh();
    triggerHistorySave();
    if (sliverDataSync) sliverDataSync.save(sliverAllData);

    // Show save status immediately
    const statusEl = document.getElementById('saveStatusSliver');
    if (statusEl) {
        statusEl.textContent = '✓ 保存しました';
        statusEl.style.color = 'var(--accent)';
        setTimeout(() => { statusEl.textContent = ''; }, 2000);
    }

    // Debounce propagation and Firebase save to prevent UI freeze
    sliverPendingSaveContext = { year: sliverCurrentYear, month: sliverCurrentMonth };
    clearTimeout(window.sliverSaveTimer);
    window.sliverSaveTimer = setTimeout(flushSliverPendingSave, 500);
}

function flushSliverPendingSave() {
    const context = sliverPendingSaveContext;
    if (!context) return;

    clearTimeout(window.sliverSaveTimer);
    window.sliverSaveTimer = null;
    sliverPendingSaveContext = null;
    propagateSliverCarryover(context.year, context.month);
    saveSliverData();
    if (sliverDataSync) sliverDataSync.flush();
}

function recalculateSliver() {
    recalculateSliverSection('p');
    recalculateSliverSection('m');
}

function recalculateSliverSection(section) {
    const key = `${sliverCurrentYear}-${sliverCurrentMonth}`;
    const data = sliverAllData[key];
    if (!data || !data[section]) return;

    const typesDef = section === 'p' ? SLIVER_P_TYPES : SLIVER_M_TYPES;
    const daysInMonth = new Date(sliverCurrentYear, sliverCurrentMonth, 0).getDate();

    const totalsObj = {};

    typesDef.forEach(t => {
        const typeData = data[section][t.key];
        if (!typeData) return;

        let balance = typeData.carryover || 0;
        let totalIn = 0, totalMorn = 0, totalEve = 0;

        for (let d = 1; d <= daysInMonth; d++) {
            const dData = (typeData.days && typeData.days[d]) || {};
            const incoming = parseInt(dData.incoming) || 0;
            const morning = parseInt(dData.morning) || 0;
            const evening = parseInt(dData.evening) || 0;

            totalIn += incoming;
            totalMorn += morning;
            totalEve += evening;

            balance = balance + incoming - morning - evening;

            const remEl = document.getElementById(`sliver-rem-${section}-${t.key}-${d}`);
            if (remEl) {
                remEl.textContent = balance;
                if (balance <= 5) {
                    remEl.classList.add('low-stock');
                } else {
                    remEl.classList.remove('low-stock');
                }
            }
        }
        totalsObj[t.key] = { incoming: totalIn, morning: totalMorn, evening: totalEve, finalRem: balance };
    });

    const tfoot = document.getElementById(`sliverFoot${section.toUpperCase()}`);
    if (tfoot) {
        let footHtml = '<tr style="background: var(--bg-main); border-top: 2px solid var(--border);">';
        footHtml += '<td class="sliver-date-col" style="font-weight:700; padding:0.75rem; white-space:nowrap;">残数</td>';
        typesDef.forEach((t) => {
            const sum = totalsObj[t.key] || { incoming: 0, morning: 0, evening: 0, finalRem: 0 };
            footHtml += `<td style="font-weight:700">${sum.incoming || ''}</td>`;
            footHtml += `<td style="font-weight:700">${sum.morning || ''}</td>`;
            footHtml += `<td style="font-weight:700">${sum.evening || ''}</td>`;
            footHtml += `<td style="font-weight:800; color:var(--primary)">${sum.finalRem}</td>`;
        });
        footHtml += '</tr>';
        tfoot.innerHTML = footHtml;
    }
}

function propagateSliverCarryover(year, month) {
    let currentYear = year;
    let currentMonth = month;

    for (let i = 0; i < 24; i++) {
        const currentKey = `${currentYear}-${currentMonth}`;
        const currentData = sliverAllData[currentKey];
        if (!currentData) break;

        const nextMonth = currentMonth === 12 ? 1 : currentMonth + 1;
        const nextYear = currentMonth === 12 ? currentYear + 1 : currentYear;
        const nextKey = `${nextYear}-${nextMonth}`;

        if (!sliverAllData[nextKey]) break;

        let changed = false;
        ['p', 'm'].forEach(section => {
            const typesDef = section === 'p' ? SLIVER_P_TYPES : SLIVER_M_TYPES;
            typesDef.forEach(t => {
                if (currentData[section] && currentData[section][t.key]) {
                    const endBal = calculateSliverEndBalance(currentData[section][t.key], currentYear, currentMonth);
                    if (sliverAllData[nextKey][section] && sliverAllData[nextKey][section][t.key]) {
                        if (sliverAllData[nextKey][section][t.key].carryover !== endBal) {
                            sliverAllData[nextKey][section][t.key].carryover = endBal;
                            changed = true;
                        }
                    }
                }
            });
        });

        if (!changed) break;
        currentYear = nextYear;
        currentMonth = nextMonth;
    }

    localStorage.setItem(SLIVER_STORAGE_KEY, JSON.stringify(sliverAllData));
                scheduleDailyBackupRefresh();
    triggerHistorySave();
}

// Expose sliver functions to global scope
window.updateSliverCell = updateSliverCell;

