function ensureSnowsprintBagData(monthData) {
    if (!monthData || typeof monthData !== 'object' || Array.isArray(monthData)) return false;

    let changed = false;
    if (!monthData.iwatsuki || typeof monthData.iwatsuki !== 'object' || Array.isArray(monthData.iwatsuki)) {
        monthData.iwatsuki = {};
        changed = true;
    }

    const iwatsukiData = monthData.iwatsuki;
    if (!iwatsukiData.bag || typeof iwatsukiData.bag !== 'object' || Array.isArray(iwatsukiData.bag)) {
        iwatsukiData.bag = {};
        changed = true;
    }

    const bagData = iwatsukiData.bag;
    if (!bagData.bag || typeof bagData.bag !== 'object' || Array.isArray(bagData.bag)) {
        bagData.bag = { carryover: 0, days: {} };
        changed = true;
    } else {
        if (!Object.prototype.hasOwnProperty.call(bagData.bag, 'carryover')) {
            bagData.bag.carryover = 0;
            changed = true;
        }
        if (!bagData.bag.days || typeof bagData.bag.days !== 'object' || Array.isArray(bagData.bag.days)) {
            bagData.bag.days = {};
            changed = true;
        }
    }

    return changed;
}

function ensureSnowsprintConfiguredItems() {
    let changed = false;
    Object.keys(snowsprintAllData || {}).forEach(key => {
        if (ensureSnowsprintBagData(snowsprintAllData[key])) changed = true;
    });
    return changed;
}

function initSnowsprint() {
    const stored = localStorage.getItem(SNOWSPRINT_STORAGE_KEY);
    if (stored) {
        try {
            snowsprintAllData = JSON.parse(stored);
        } catch (e) {
            snowsprintAllData = JSON.parse(JSON.stringify(SNOWSPRINT_INITIAL_DATA));
        }
    } else {
        snowsprintAllData = JSON.parse(JSON.stringify(SNOWSPRINT_INITIAL_DATA));
        localStorage.setItem(SNOWSPRINT_STORAGE_KEY, JSON.stringify(snowsprintAllData));
                scheduleDailyBackupRefresh();
    }

    ensureSnowsprintMonth(snowsprintCurrentYear, snowsprintCurrentMonth, false);
    const snowsprintConfigChanged = ensureSnowsprintConfiguredItems();
    // Initial catch-up propagation
    propagateSnowSprintCarryover(snowsprintCurrentYear, snowsprintCurrentMonth);
    setupSnowsprintMonthSelector();

    if (database && window.SharedSync && !snowsprintDataSync) {
        snowsprintDataSync = SharedSync.createPathSync({
            database,
            path: SNOWSPRINT_DB_PATH,
            emptyValue: {},
            pendingStorageKey: SNOWSPRINT_STORAGE_KEY + '_pending_sync',
            serverSnapshotStorageKey: SNOWSPRINT_STORAGE_KEY + '_server_snapshot',
            getLocal: () => snowsprintAllData,
            setLocal: value => {
                snowsprintAllData = value;
                if (ensureSnowsprintConfiguredItems()) snowsprintConfigNeedsSync = true;
                localStorage.setItem(SNOWSPRINT_STORAGE_KEY, JSON.stringify(snowsprintAllData));
                scheduleDailyBackupRefresh();
            },
            onRemote: () => {
                const configChanged = ensureSnowsprintConfiguredItems() || snowsprintConfigNeedsSync;
                if (configChanged && snowsprintDataSync) {
                    snowsprintConfigNeedsSync = false;
                    snowsprintDataSync.save(snowsprintAllData);
                }
                const activeEl = document.activeElement;
                ensureSnowsprintMonth(snowsprintCurrentYear, snowsprintCurrentMonth, true);
                if (!activeEl?.closest('#snowsprint-view-container')
                    && snowsprintViewContainer.style.display === 'block') renderSnowsprint();
            }
        });
    }

    if (snowsprintConfigChanged) {
        localStorage.setItem(SNOWSPRINT_STORAGE_KEY, JSON.stringify(snowsprintAllData));
        scheduleDailyBackupRefresh();
        if (snowsprintDataSync) {
            snowsprintConfigNeedsSync = false;
            snowsprintDataSync.save(snowsprintAllData);
        }
    }
}

function ensureSnowsprintMonth(year, month, shouldSave = true) {
    const key = `${year}-${month}`;
    if (!snowsprintAllData[key]) {
        let prevY = year;
        let prevM = month - 1;
        if (prevM === 0) { prevY--; prevM = 12; }
        const prevKey = `${prevY}-${prevM}`;
        const prevData = snowsprintAllData[prevKey];
        
        // Use previous month's actual data structure (like sliver/roll inventory)
        // Fall back to initial data template only if no previous month exists
        const sourceData = prevData || SNOWSPRINT_INITIAL_DATA['2025-5'] || {};
        const newData = JSON.parse(JSON.stringify(sourceData));
        
        const lastDay = prevData ? new Date(prevY, prevM, 0).getDate() : 0;
        
        const resetDaysAndCalculateCarry = (obj, prevObj) => {
            if (typeof obj === 'object' && obj !== null) {
                if (obj.hasOwnProperty('carryover') && obj.hasOwnProperty('days')) {
                    // Calculate end balance from previous month's data
                    if (prevObj) {
                        let rem = prevObj.carryover || 0;
                        if (prevObj.days) {
                            for (let i = 1; i <= lastDay; i++) {
                                const d = prevObj.days[i];
                                if (d) {
                                    rem += (d.arrival || 0) - (d.usage || 0);
                                }
                            }
                        }
                        obj.carryover = rem;
                    } else {
                        obj.carryover = 0;
                    }
                    // Reset days for the new month
                    obj.days = {};
                } else {
                    for (let k in obj) {
                        resetDaysAndCalculateCarry(obj[k], prevObj ? prevObj[k] : null);
                    }
                }
            }
        };
        
        resetDaysAndCalculateCarry(newData, prevData);
        snowsprintAllData[key] = newData;
        if (shouldSave) saveSnowsprintData(false); // 自動作成時は履歴を作動させない
    }
}

function setupSnowsprintMonthSelector() {
    const ySel = document.getElementById('yearSelectSnowsprint');
    const mSel = document.getElementById('monthSelectSnowsprint');
    const pBtn = document.getElementById('prevMonthSnowsprint');
    const nBtn = document.getElementById('nextMonthSnowsprint');

    if (!ySel || !mSel) return;

    ySel.innerHTML = '';
    for (let y = 2024; y <= 2100; y++) {
        const opt = document.createElement('option');
        opt.value = y; opt.textContent = y; ySel.appendChild(opt);
    }
    mSel.innerHTML = '';
    for (let m = 1; m <= 12; m++) {
        const opt = document.createElement('option');
        opt.value = m; opt.textContent = m; mSel.appendChild(opt);
    }

    ySel.value = snowsprintCurrentYear;
    mSel.value = snowsprintCurrentMonth;

    const update = () => {
        snowsprintCurrentYear = parseInt(ySel.value);
        snowsprintCurrentMonth = parseInt(mSel.value);
        ensureSnowsprintMonth(snowsprintCurrentYear, snowsprintCurrentMonth);
        renderSnowsprint();
    };

    ySel.addEventListener('change', update);
    mSel.addEventListener('change', update);

    pBtn?.addEventListener('click', () => {
        let y = parseInt(ySel.value), m = parseInt(mSel.value);
        m--; if (m < 1) { m = 12; y--; }
        if (y >= 2024) { ySel.value = y; mSel.value = m; update(); }
    });
    nBtn?.addEventListener('click', () => {
        let y = parseInt(ySel.value), m = parseInt(mSel.value);
        m++; if (m > 12) { m = 1; y++; }
        if (y <= 2030) { ySel.value = y; mSel.value = m; update(); }
    });
}

function saveSnowsprintData() {
    if (!canWriteAppData()) return false;
    localStorage.setItem(SNOWSPRINT_STORAGE_KEY, JSON.stringify(snowsprintAllData));
                scheduleDailyBackupRefresh();
    triggerHistorySave();
    if (database) {
        // 空データ保護
        if (Object.keys(snowsprintAllData).length === 0) {
            console.warn('BLOCKED: Attempted to save empty snowsprintAllData to Firebase');
            return;
        }
        if (snowsprintDataSync) snowsprintDataSync.save(snowsprintAllData);
        const el = document.getElementById('saveStatusSnowsprint');
        if (el) {
            el.textContent = '\u4fdd\u5b58\u3057\u307e\u3057\u305f ' + new Date().toLocaleTimeString();
            setTimeout(() => el.textContent = '', 3000);
        }
    }
}

function handleSnowsprintInput(e) {
    const target = e.target;
    if (!target.classList.contains('snowsprint-input')) return;
    
    let val = target.value.trim();
    if (val === '') val = 0; else val = parseInt(val);
    if (isNaN(val)) return;

    const category = target.dataset.category;
    const type1 = target.dataset.type1;
    const type2 = target.dataset.type2;
    const field = target.dataset.field;
    
    const key = `${snowsprintCurrentYear}-${snowsprintCurrentMonth}`;
    const dataObj = snowsprintAllData[key][category][type1][type2];

    if (field === "carryover") {
        dataObj.carryover = val;
    } else {
        const day = target.dataset.day;
        if (!dataObj.days) dataObj.days = {};
        if (!dataObj.days[day]) dataObj.days[day] = {};
        if (val === 0) {
            delete dataObj.days[day][field];
        } else {
            dataObj.days[day][field] = val;
        }
    }

    // Persist the edited value before the delayed carryover calculation.
    // This creates a SharedSync pending record immediately on iPhone too.
    localStorage.setItem(SNOWSPRINT_STORAGE_KEY, JSON.stringify(snowsprintAllData));
    scheduleDailyBackupRefresh();
    triggerHistorySave();
    if (snowsprintDataSync) snowsprintDataSync.save(snowsprintAllData);

    snowsprintPendingSaveContext = {
        year: snowsprintCurrentYear,
        month: snowsprintCurrentMonth
    };
    clearTimeout(snowsprintSaveTimer);
    snowsprintSaveTimer = setTimeout(flushSnowsprintPendingSave, 500);
}

function flushSnowsprintPendingSave() {
    const context = snowsprintPendingSaveContext;
    if (!context) return;

    clearTimeout(snowsprintSaveTimer);
    snowsprintSaveTimer = null;
    snowsprintPendingSaveContext = null;
    propagateSnowSprintCarryover(context.year, context.month);
    saveSnowsprintData();
    if (snowsprintDataSync) snowsprintDataSync.flush();
}

function handleSnowsprintChange(e) {
    recalculateSnowsprint();
}

function getSnowsprintBalance(dataObj, maxDay) {
    if (!dataObj) return 0;
    const carry = parseInt(dataObj.carryover);
    let rem = isNaN(carry) ? 0 : carry;
    if (!dataObj.days) return rem;
    for (let i = 1; i <= maxDay; i++) {
        const d = dataObj.days[i];
        if (d) {
            rem += (parseInt(d.arrival) || 0) - (parseInt(d.usage) || 0);
        }
    }
    return rem;
}

function renderSnowsprintGeneric(headId, bodyId, footId, configGroups, category) {
    const head = document.getElementById(headId);
    const body = document.getElementById(bodyId);
    const foot = document.getElementById(footId);
    if (!head || !body || !foot) return;

    let trMain = '<tr class="header-main-stock"><th rowspan="3" class="date-col-stock">日付</th>';
    let trSub1 = '<tr class="header-sub-stock">';
    let trSub2 = '<tr class="header-sub-stock">';
    
    configGroups.forEach((group) => {
        trMain += `<th colspan="${group.items.length * 3}" class="group-film-stock" style="background: ${group.bg}; color: ${group.color}; border: 1px solid var(--border);">${group.title}</th>`;
        group.items.forEach((item) => {
            trSub1 += `<th colspan="3" class="sub-film-stock" style="background: ${item.bg}; text-align: center; border: 1px solid var(--border);">${item.title}</th>`;
            trSub2 += `
                <th class="sub-film-stock"><span class="snow-text-desktop">入荷</span><span class="snow-text-mobile">入荷</span></th>
                <th class="sub-film-stock"><span class="usage-text-desktop">使用数</span><span class="usage-text-mobile">使用</span></th>
                <th class="sub-film-stock remaining-stock"><span class="snow-text-desktop">残数</span><span class="snow-text-mobile">残</span></th>
            `;
        });
    });
    trMain += '</tr>';
    trSub1 += '</tr>';
    trSub2 += '</tr>';
    head.innerHTML = trMain + trSub1 + trSub2;

    const dataKey = `${snowsprintCurrentYear}-${snowsprintCurrentMonth}`;
    let mData = snowsprintAllData[dataKey];
    if (!mData) {
        ensureSnowsprintMonth(snowsprintCurrentYear, snowsprintCurrentMonth);
        mData = snowsprintAllData[dataKey];
        if (!mData) return;
    }
    const secData = mData[category] || {};

    const getObj = (t1, t2) => {
        if (!secData[t1]) secData[t1] = {};
        if (!secData[t1][t2]) secData[t1][t2] = { carryover: 0, days: {} };
        return secData[t1][t2];
    };

    let carryRow = `<tr class="carryover-row" style="background: rgba(var(--primary-rgb), 0.05);"><td style="font-weight:700; padding:0.5rem; white-space:nowrap; border: 1px solid var(--border);">
        <span class="carryover-text-desktop">前月繰越</span>
        <span class="carryover-text-mobile">繰越</span>
    </td>`;
    configGroups.forEach(group => {
        group.items.forEach(item => {
            const dataObj = getObj(group.id, item.id);
            const hasCarryComment = (dataObj.carryover_comments || []).length > 0;
            const carryCommentTip = hasCarryComment ? escapeHtmlAttr(dataObj.carryover_comments[dataObj.carryover_comments.length - 1].text) : '';
            // Three columns per item: empty, empty, and carryover input in the balance column
            carryRow += `
                <td style="border: 1px solid var(--border);"></td>
                <td style="border: 1px solid var(--border);"></td>
                <td class="remaining-stock carry-cell${hasCarryComment ? ' sn-has-comment' : ''}" style="border: 1px solid var(--border); text-align: center; position: relative;" ${hasCarryComment ? 'title="' + carryCommentTip + '"' : ''}>
                    <input type="number" class="snowsprint-input carry-input" 
                        data-category="${category}" data-type1="${group.id}" data-type2="${item.id}" data-field="carryover"
                        value="${dataObj.carryover || 0}" min="0" style="width: 90%; background: transparent; border: none; font-weight: 800; color: var(--primary); text-align: center; padding: 2px;">
                </td>`;
        });
    });
    carryRow += '</tr>';
    
    const daysInMonth = new Date(snowsprintCurrentYear, snowsprintCurrentMonth, 0).getDate();
    let bodyRows = '';
    const todayStr = currentDate;
    
    for (let d = 1; d <= daysInMonth; d++) {
        const isHoliday = isRollHoliday(snowsprintCurrentYear, snowsprintCurrentMonth, d);
        const dObj = new Date(snowsprintCurrentYear, snowsprintCurrentMonth - 1, d);
        const dayOfWeek = dObj.getDay();
        const dateStr = `${snowsprintCurrentYear}-${String(snowsprintCurrentMonth).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const isToday = dateStr === todayStr;
        
        let rowClass = '';
        if (isToday) {
            rowClass = 'sliver-row-today';
        } else if (isHoliday) {
            rowClass = 'weekend-holiday';
        } else if (dayOfWeek === 0) {
            rowClass = 'weekend-sun';
        } else if (dayOfWeek === 6) {
            rowClass = 'weekend-sat';
        }
        
        bodyRows += `<tr class="${rowClass}" data-day="${d}">
            <td class="date-cell" style="border: 1px solid var(--border);">
                <div class="date-desktop">${snowsprintCurrentMonth}/${d}(${['日','月','火','水','木','金','土'][dayOfWeek]})</div>
                <div class="date-mobile">
                    <div class="date-num">${d}</div>
                    <div class="day-name">${['日','月','火','水','木','金','土'][dayOfWeek]}</div>
                </div>
            </td>`;
            
        configGroups.forEach(group => {
            group.items.forEach(item => {
                const dataObj = getObj(group.id, item.id);
                const dayData = (dataObj.days && dataObj.days[d]) ? dataObj.days[d] : {};
                const arr = dayData.arrival || '';
                const usa = dayData.usage || '';
                const bal = getSnowsprintBalance(dataObj, d);
                const arrComments = dayData.arrival_comments || [];
                const usaComments = dayData.usage_comments || [];
                const hasArrComment = arrComments.length > 0;
                const hasUsaComment = usaComments.length > 0;
                
                bodyRows += `
                    <td class="${hasArrComment ? 'sn-has-comment' : ''}" style="border: 1px solid var(--border); padding: 0.25rem; position: relative;" ${hasArrComment ? 'title="' + escapeHtmlAttr(arrComments[arrComments.length-1].text) + '"' : ''}><input type="number" class="snowsprint-input stock-input" data-category="${category}" data-type1="${group.id}" data-type2="${item.id}" data-field="arrival" data-day="${d}" value="${arr}" min="0" style="width: 100%; border: none; padding: 4px; text-align: center;"></td>
                    <td class="${hasUsaComment ? 'sn-has-comment' : ''}" style="border: 1px solid var(--border); padding: 0.25rem; position: relative;" ${hasUsaComment ? 'title="' + escapeHtmlAttr(usaComments[usaComments.length-1].text) + '"' : ''}><input type="number" class="snowsprint-input stock-input" data-category="${category}" data-type1="${group.id}" data-type2="${item.id}" data-field="usage" data-day="${d}" value="${usa}" min="0" style="width: 100%; border: none; padding: 4px; text-align: center;"></td>
                    <td class="remaining-stock ${bal < STOCK_LOW_THRESHOLD ? 'low-stock' : ''}" style="border: 1px solid var(--border);">${bal}</td>
                `;
            });
        });
        bodyRows += '</tr>';
    }
    
    body.innerHTML = carryRow + bodyRows;
    
    let footHtml = '<tr><td style="font-weight:700; border: 1px solid var(--border); text-align: center;">残</td>';
    configGroups.forEach(group => {
        group.items.forEach(item => {
            const dataObj = getObj(group.id, item.id);
            const bal = getSnowsprintBalance(dataObj, daysInMonth);
            footHtml += `
                <td style="font-weight:700; border: 1px solid var(--border); background: rgba(var(--primary-rgb), 0.05);">残</td>
                <td style="border: 1px solid var(--border);"></td>
                <td class="remaining-stock" style="font-weight:800; border: 1px solid var(--border); background: rgba(var(--primary-rgb), 0.05);">${bal}</td>
            `;
        });
    });
    footHtml += '</tr>';
    foot.innerHTML = footHtml;

    body.querySelectorAll('.snowsprint-input').forEach(el => {
        el.addEventListener('input', (e) => { 
            snowsprintLastEditTime = Date.now(); 
            handleSnowsprintInput(e);
        });
        el.addEventListener('change', handleSnowsprintChange);
        el.addEventListener('blur', flushSnowsprintPendingSave);
    });

    // Attach right-click (PC) and gestures (Mobile) for comment popup on input cells
    body.querySelectorAll('td').forEach(td => {
        const input = td.querySelector('.snowsprint-input');
        if (!input) return;
        
        const getCellInfo = () => ({
            category: input.dataset.category,
            type1: input.dataset.type1,
            type2: input.dataset.type2,
            field: input.dataset.field,
            day: input.dataset.day || null
        });

        const handleOpen = (e) => {
            if (e && e.preventDefault) e.preventDefault();
            if (document.activeElement === input) {
                input.blur();
            }
            openSnowsprintComment(getCellInfo(), td);
        };

        // --- PC Right Click ---
        td.addEventListener('contextmenu', handleOpen);

        // --- Mobile Gestures (Double Tap & Long Press) ---
        let pressTimer = null;
        let lastTap = 0;
        
        td.addEventListener('touchstart', (e) => {
            if (e.touches && e.touches.length > 1) return; // Ignore multi-touch
            
            const currentTime = new Date().getTime();
            const tapLength = currentTime - lastTap;
            
            if (tapLength > 0 && tapLength < 400) {
                // Double tap detected
                clearTimeout(pressTimer);
                handleOpen(e);
                lastTap = 0;
                return;
            }
            lastTap = currentTime;

            // Long press detected
            pressTimer = setTimeout(() => {
                if (window.navigator && window.navigator.vibrate) {
                    window.navigator.vibrate(50);
                }
                handleOpen();
            }, 600);
        }, { passive: false });

        const cancelPress = () => {
            if (pressTimer) clearTimeout(pressTimer);
        };

        td.addEventListener('touchend', cancelPress);
        td.addEventListener('touchmove', cancelPress);
        td.addEventListener('touchcancel', cancelPress);
    });

    carryRow = null; bodyRows = null; footHtml = null;
}

function recalculateSnowsprint() {
    renderSnowsprint();
}

function renderSnowsprintSizeTabs() {
    const container = document.getElementById('snSizeTabs');
    if (!container) return;
    const product = SNOWSPRINT_TAB_CONFIG[snowsprintActiveProduct];
    if (!product) return;

    container.innerHTML = product.sizes.map((size, i) =>
        `<button class="sn-size-tab${i === snowsprintActiveSize ? ' active' : ''}" data-size="${i}" onclick="switchSnowsprintSize(${i})">${size.label}</button>`
    ).join('');
}

function switchSnowsprintProduct(idx) {
    closeSnowsprintComment();
    snowsprintActiveProduct = idx;
    snowsprintActiveSize = 0;

    // Update product tab active state
    document.querySelectorAll('.sn-product-tab').forEach(btn => {
        btn.classList.toggle('active', parseInt(btn.dataset.product) === idx);
    });

    renderSnowsprintSizeTabs();
    renderSnowsprint();
}
window.switchSnowsprintProduct = switchSnowsprintProduct;

function switchSnowsprintSize(idx) {
    closeSnowsprintComment();
    snowsprintActiveSize = idx;

    // Update size tab active state
    document.querySelectorAll('.sn-size-tab').forEach(btn => {
        btn.classList.toggle('active', parseInt(btn.dataset.size) === idx);
    });

    renderSnowsprint();
}
window.switchSnowsprintSize = switchSnowsprintSize;

function renderSnowsprint() {
    closeSnowsprintComment();
    const product = SNOWSPRINT_TAB_CONFIG[snowsprintActiveProduct];
    if (!product) return;

    // Ensure size tabs are rendered
    const sizeTabsEl = document.getElementById('snSizeTabs');
    if (sizeTabsEl && sizeTabsEl.children.length === 0) {
        renderSnowsprintSizeTabs();
    }

    // Clamp active size index
    if (snowsprintActiveSize >= product.sizes.length) {
        snowsprintActiveSize = 0;
    }

    const sizeConfig = product.sizes[snowsprintActiveSize];
    if (!sizeConfig) return;

    renderSnowsprintGeneric('snTabHead', 'snTabBody', 'snTabFoot', sizeConfig.config, sizeConfig.category);
}

// ========================================================= //
// ======= Snow Sprint Comment System (Sheets-style) ======= //
// ========================================================= //

function escapeHtmlAttr(str) {
    return (str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function getSnowsprintCellComments(category, type1, type2, field, day) {
    try {
        const key = `${snowsprintCurrentYear}-${snowsprintCurrentMonth}`;
        const dataObj = snowsprintAllData[key][category][type1][type2];
        if (field === 'carryover') {
            return dataObj.carryover_comments || [];
        }
        return (dataObj.days && dataObj.days[day] && dataObj.days[day][`${field}_comments`]) || [];
    } catch (e) {
        return [];
    }
}

function setSnowsprintCellComments(category, type1, type2, field, day, comments) {
    const key = `${snowsprintCurrentYear}-${snowsprintCurrentMonth}`;
    if (!snowsprintAllData[key]) return;
    const secData = snowsprintAllData[key][category];
    if (!secData || !secData[type1] || !secData[type1][type2]) return;
    const dataObj = secData[type1][type2];

    if (field === 'carryover') {
        if (comments.length > 0) {
            dataObj.carryover_comments = comments;
        } else {
            delete dataObj.carryover_comments;
        }
    } else {
        if (!dataObj.days) dataObj.days = {};
        if (!dataObj.days[day]) dataObj.days[day] = {};
        if (comments.length > 0) {
            dataObj.days[day][`${field}_comments`] = comments;
        } else {
            delete dataObj.days[day][`${field}_comments`];
            // Clean up empty day objects (only if no arrival/usage data remains)
            const remaining = Object.keys(dataObj.days[day]);
            if (remaining.length === 0) {
                delete dataObj.days[day];
            }
        }
    }

    snowsprintLastEditTime = Date.now();
    saveSnowsprintData();
}

function getSnowsprintCommentCellLabel(cellInfo) {
    const { category, type1, type2, field, day } = cellInfo;
    const fieldLabels = { arrival: '入荷', usage: '使用数', carryover: '前月繰越' };
    const fieldLabel = fieldLabels[field] || field;
    const dayLabel = day ? `${snowsprintCurrentMonth}/${day}` : '';
    // Build a readable label
    let label = '';
    if (dayLabel) label += dayLabel + ' ';
    label += fieldLabel;
    return label;
}

function openSnowsprintComment(cellInfo, anchorEl) {
    snCommentCurrentCell = cellInfo;

    const overlay = document.getElementById('snCommentOverlay');
    const popup = document.getElementById('snCommentPopup');
    const cellInfoEl = document.getElementById('snCommentCellInfo');
    const input = document.getElementById('snCommentInput');

    // Set cell info label
    cellInfoEl.textContent = getSnowsprintCommentCellLabel(cellInfo);

    // Render existing comments
    renderSnowsprintCommentList();

    // Position popup near the clicked cell
    const rect = anchorEl.getBoundingClientRect();
    const isMobile = window.innerWidth <= 600;

    if (!isMobile) {
        const popupWidth = 340;
        let left = rect.right + 8;
        let top = rect.top;

        // Keep popup on screen
        if (left + popupWidth > window.innerWidth) {
            left = rect.left - popupWidth - 8;
        }
        if (left < 8) left = 8;
        if (top + 400 > window.innerHeight) {
            top = Math.max(8, window.innerHeight - 400);
        }

        popup.style.left = left + 'px';
        popup.style.top = top + 'px';
    }

    // Show overlay and popup
    overlay.classList.add('active');
    popup.classList.add('active');

    // Focus input
    input.value = '';
    setTimeout(() => input.focus(), 100);
}

function closeSnowsprintComment() {
    const overlay = document.getElementById('snCommentOverlay');
    const popup = document.getElementById('snCommentPopup');
    if (overlay) overlay.classList.remove('active');
    if (popup) popup.classList.remove('active');
    snCommentCurrentCell = null;
}

function submitSnowsprintComment() {
    if (!snCommentCurrentCell) return;
    const input = document.getElementById('snCommentInput');
    const text = input.value.trim();
    if (!text) return;

    const { category, type1, type2, field, day } = snCommentCurrentCell;
    const comments = getSnowsprintCellComments(category, type1, type2, field, day);

    comments.push({ text: text, time: Date.now() });
    setSnowsprintCellComments(category, type1, type2, field, day, comments);

    input.value = '';
    renderSnowsprintCommentList();

    // Update cell indicator without full re-render
    updateSnowsprintCellIndicator(category, type1, type2, field, day);
}

function deleteSnowsprintComment(index) {
    if (!snCommentCurrentCell) return;
    const { category, type1, type2, field, day } = snCommentCurrentCell;
    const comments = getSnowsprintCellComments(category, type1, type2, field, day);

    comments.splice(index, 1);
    setSnowsprintCellComments(category, type1, type2, field, day, comments);

    renderSnowsprintCommentList();
    updateSnowsprintCellIndicator(category, type1, type2, field, day);

    // If no comments left, close popup
    if (comments.length === 0) {
        closeSnowsprintComment();
    }
}
window.deleteSnowsprintComment = deleteSnowsprintComment;

function updateSnowsprintCellIndicator(category, type1, type2, field, day) {
    // Find the input matching these data attributes
    const selector = field === 'carryover'
        ? `.snowsprint-input[data-category="${category}"][data-type1="${type1}"][data-type2="${type2}"][data-field="carryover"]`
        : `.snowsprint-input[data-category="${category}"][data-type1="${type1}"][data-type2="${type2}"][data-field="${field}"][data-day="${day}"]`;

    const input = document.querySelector(selector);
    if (!input) return;

    const td = input.closest('td');
    if (!td) return;

    const comments = getSnowsprintCellComments(category, type1, type2, field, day);
    if (comments.length > 0) {
        td.classList.add('sn-has-comment');
        td.title = comments[comments.length - 1].text;
    } else {
        td.classList.remove('sn-has-comment');
        td.title = '';
    }
}

function renderSnowsprintCommentList() {
    if (!snCommentCurrentCell) return;
    const listEl = document.getElementById('snCommentList');
    const { category, type1, type2, field, day } = snCommentCurrentCell;
    const comments = getSnowsprintCellComments(category, type1, type2, field, day);

    if (comments.length === 0) {
        listEl.innerHTML = '';
        return;
    }

    listEl.innerHTML = comments.map((c, i) => {
        const date = new Date(c.time);
        const timeStr = `${date.getMonth()+1}/${date.getDate()} ${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`;
        return `
            <div class="sn-comment-item">
                <div class="sn-comment-item-header">
                    <div class="sn-comment-author-area">
                        <div class="sn-comment-avatar">U</div>
                        <span class="sn-comment-author">ユーザー</span>
                        <span class="sn-comment-time">${timeStr}</span>
                    </div>
                    <button class="sn-comment-delete" onclick="deleteSnowsprintComment(${i})" title="削除">🗑</button>
                </div>
                <div class="sn-comment-text">${escapeHtmlAttr(c.text)}</div>
            </div>
        `;
    }).join('');
}

// Wire up comment popup event listeners
(function initCommentPopup() {
    document.getElementById('snCommentClose')?.addEventListener('click', closeSnowsprintComment);
    document.getElementById('snCommentOverlay')?.addEventListener('click', closeSnowsprintComment);
    document.getElementById('snCommentSubmit')?.addEventListener('click', submitSnowsprintComment);
    document.getElementById('snCommentInput')?.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            submitSnowsprintComment();
        }
    });
    // Close on Escape key
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && snCommentCurrentCell) {
            closeSnowsprintComment();
        }
    });
})();

// Finally, start the application
// init() moved to the end of the file
function propagateSnowSprintCarryover(year, month) {
    let curY = parseInt(year);
    let curM = parseInt(month);
    
    // Propagate up to 24 months
    for (let i = 0; i < 24; i++) {
        const curKey = `${curY}-${curM}`;
        const curData = snowsprintAllData[curKey];
        if (!curData) break;

        let nextM = curM + 1;
        let nextY = curY;
        if (nextM > 12) { nextM = 1; nextY++; }
        
        const nextKey = `${nextY}-${nextM}`;
        if (!snowsprintAllData[nextKey]) break;

        const nextData = snowsprintAllData[nextKey];

        const syncObjects = (cData, nData) => {
            if (!cData || !nData) return;
            for (const k in cData) {
                if (!nData[k]) continue;
                const cObj = cData[k];
                const nObj = nData[k];
                if (cObj && nObj && typeof cObj === 'object') {
                    // Check if this is a leaf node (item level)
                    if ('carryover' in cObj) {
                        const lastDay = new Date(curY, curM, 0).getDate();
                        const endBal = getSnowsprintBalance(cObj, lastDay);
                        
                        // Force update next month's carryover
                        nObj.carryover = endBal;
                        
                        // Ensure days object exists in next month
                        if (!nObj.days) nObj.days = {};
                    } else {
                        // Recurse deeper into categories/groups
                        syncObjects(cObj, nObj);
                    }
                }
            }
        };

        syncObjects(curData, nextData);
        
        curY = nextY;
        curM = nextM;
    }
    localStorage.setItem(SNOWSPRINT_STORAGE_KEY, JSON.stringify(snowsprintAllData));
    scheduleDailyBackupRefresh();
}

// ==========================================
// ===== Hanapon Box Inventory Management ====
// ==========================================

const HANAPON_BOX_STORAGE_KEY = 'hanaponBoxInventoryData';
const HANAPON_BOX_DB_PATH = `${SECRET_KEY}/${isProduction ? 'hanapon_box_inventory' : 'hanapon_box_inventory_dev'}`;
const HANAPON_BOX_TYPES = [
    { key: 'ariake', name: '0649', bg: '#e0e7ff', color: '#4338ca' },
    { key: 'materials', name: '0588', bg: '#d1fae5', color: '#047857' },
    { key: 'large', name: '大', bg: '#fef3c7', color: '#b45309' }
];
const HANAPON_BOX_COMPANIES = [
    { key: 'limited', name: '有限' },
    { key: 'stock', name: '株式' }
];
const HANAPON_BOX_LEGACY_COMPANY_KEY = 'limited';

let hanaponBoxAllData = {};
let hanaponBoxSaveTimer = null;
let hanaponBoxPendingSaveContext = null;
let hanaponBoxCurrentYear = new Date().getFullYear();
let hanaponBoxCurrentMonth = new Date().getMonth() + 1;
let hanaponBoxActiveCompany = HANAPON_BOX_LEGACY_COMPANY_KEY;

function isHanaponBoxObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function cloneHanaponBoxValue(value) {
    if (value === undefined) return undefined;
    try {
        return JSON.parse(JSON.stringify(value));
    } catch (error) {
        return value;
    }
}

function createHanaponBoxType(type, carryover = 0) {
    return {
        name: type.name,
        carryover: Number.isNaN(parseInt(carryover, 10)) ? 0 : parseInt(carryover, 10),
        days: {}
    };
}

function normalizeHanaponBoxType(typeData, type) {
    const normalized = isHanaponBoxObject(typeData)
        ? cloneHanaponBoxValue(typeData)
        : createHanaponBoxType(type);
    normalized.name = type.name;
    const carryover = parseInt(normalized.carryover, 10);
    normalized.carryover = Number.isNaN(carryover) ? 0 : carryover;
    if (!isHanaponBoxObject(normalized.days)) normalized.days = {};
    return normalized;
}

function syncHanaponBoxLegacyMonth(monthData) {
    if (!isHanaponBoxObject(monthData) || !isHanaponBoxObject(monthData[HANAPON_BOX_LEGACY_COMPANY_KEY])) return;
    HANAPON_BOX_TYPES.forEach(type => {
        const typeData = monthData[HANAPON_BOX_LEGACY_COMPANY_KEY][type.key];
        if (isHanaponBoxObject(typeData)) monthData[type.key] = cloneHanaponBoxValue(typeData);
    });
}

function getHanaponBoxPreviousType(previousData, companyKey, typeKey) {
    if (!isHanaponBoxObject(previousData)) return null;
    const companyData = previousData[companyKey];
    if (isHanaponBoxObject(companyData) && isHanaponBoxObject(companyData[typeKey])) {
        return companyData[typeKey];
    }
    if (companyKey === HANAPON_BOX_LEGACY_COMPANY_KEY && isHanaponBoxObject(previousData[typeKey])) {
        return previousData[typeKey];
    }
    return null;
}

function normalizeHanaponBoxData(value) {
    let data = {};
    if (isHanaponBoxObject(value)) {
        try {
            data = JSON.parse(JSON.stringify(value));
        } catch (error) {
            data = {};
        }
    }

    Object.keys(data).forEach(monthKey => {
        const monthData = data[monthKey];
        if (!isHanaponBoxObject(monthData)) return;

        const legacyTypes = {};
        HANAPON_BOX_TYPES.forEach(type => {
            if (isHanaponBoxObject(monthData[type.key])) {
                legacyTypes[type.key] = normalizeHanaponBoxType(monthData[type.key], type);
            }
        });

        HANAPON_BOX_COMPANIES.forEach(company => {
            const existingCompany = isHanaponBoxObject(monthData[company.key])
                ? monthData[company.key]
                : {};
            const companyData = {};
            HANAPON_BOX_TYPES.forEach(type => {
                const existingType = existingCompany[type.key];
                const legacyType = company.key === HANAPON_BOX_LEGACY_COMPANY_KEY
                    ? legacyTypes[type.key]
                    : null;
                companyData[type.key] = normalizeHanaponBoxType(existingType || legacyType, type);
            });
            monthData[company.key] = companyData;
        });

        // Keep the old three top-level fields as a compatibility copy for an
        // already-open older page. New edits are made in the company tabs.
        syncHanaponBoxLegacyMonth(monthData);
    });

    return data;
}

function createHanaponBoxMonth(previousData, previousYear, previousMonth) {
    const monthData = {};
    HANAPON_BOX_COMPANIES.forEach(company => {
        const companyData = {};
        HANAPON_BOX_TYPES.forEach(type => {
            const previousType = getHanaponBoxPreviousType(previousData, company.key, type.key);
            companyData[type.key] = createHanaponBoxType(
                type,
                previousType
                    ? calculateHanaponBoxEndBalance(previousType, previousYear, previousMonth)
                    : 0
            );
        });
        monthData[company.key] = companyData;
    });
    syncHanaponBoxLegacyMonth(monthData);
    return monthData;
}

function ensureHanaponBoxMonth(year, month, shouldSave = true) {
    const key = `${year}-${month}`;
    const previousMonth = month === 1 ? 12 : month - 1;
    const previousYear = month === 1 ? year - 1 : year;
    const previousData = hanaponBoxAllData[`${previousYear}-${previousMonth}`];

    if (!hanaponBoxAllData[key]) {
        hanaponBoxAllData[key] = createHanaponBoxMonth(previousData, previousYear, previousMonth);
        if (shouldSave) saveHanaponBoxData(false);
        return;
    }

    const monthData = hanaponBoxAllData[key];
    if (!isHanaponBoxObject(monthData)) return;

    const legacyTypes = {};
    HANAPON_BOX_TYPES.forEach(type => {
        if (isHanaponBoxObject(monthData[type.key])) {
            legacyTypes[type.key] = normalizeHanaponBoxType(monthData[type.key], type);
        }
    });

    HANAPON_BOX_COMPANIES.forEach(company => {
        const companyData = isHanaponBoxObject(monthData[company.key])
            ? monthData[company.key]
            : {};
        HANAPON_BOX_TYPES.forEach(type => {
            if (isHanaponBoxObject(companyData[type.key])) {
                companyData[type.key] = normalizeHanaponBoxType(companyData[type.key], type);
                return;
            }

            const legacyType = company.key === HANAPON_BOX_LEGACY_COMPANY_KEY
                ? legacyTypes[type.key]
                : null;
            const previousType = getHanaponBoxPreviousType(previousData, company.key, type.key);
            companyData[type.key] = legacyType
                ? normalizeHanaponBoxType(legacyType, type)
                : createHanaponBoxType(
                    type,
                    previousType
                        ? calculateHanaponBoxEndBalance(previousType, previousYear, previousMonth)
                        : 0
                );
        });
        monthData[company.key] = companyData;
    });

    syncHanaponBoxLegacyMonth(monthData);
}

function calculateHanaponBoxEndBalance(typeData, year, month, throughDay = null) {
    if (!typeData || typeof typeData !== 'object') return 0;
    let balance = parseInt(typeData.carryover, 10);
    if (Number.isNaN(balance)) balance = 0;

    const daysInMonth = throughDay || new Date(year, month, 0).getDate();
    for (let day = 1; day <= daysInMonth; day++) {
        const dayData = typeData.days && typeData.days[day];
        balance += parseInt(dayData?.incoming, 10) || 0;
        balance -= parseInt(dayData?.usage, 10) || 0;
    }
    return balance;
}

function refreshHanaponBoxMonthCarryover(year, month, companyKey = hanaponBoxActiveCompany) {
    if (!HANAPON_BOX_COMPANIES.some(company => company.key === companyKey)) {
        companyKey = HANAPON_BOX_LEGACY_COMPANY_KEY;
    }

    const currentYear = parseInt(year, 10);
    const currentMonth = parseInt(month, 10);
    const previousMonth = currentMonth === 1 ? 12 : currentMonth - 1;
    const previousYear = currentMonth === 1 ? currentYear - 1 : currentYear;
    const currentData = hanaponBoxAllData[`${currentYear}-${currentMonth}`];
    const previousData = hanaponBoxAllData[`${previousYear}-${previousMonth}`];
    const currentCompanyData = currentData?.[companyKey];
    if (!isHanaponBoxObject(currentData)
        || !isHanaponBoxObject(previousData)
        || !isHanaponBoxObject(currentCompanyData)) return false;

    let changed = false;
    HANAPON_BOX_TYPES.forEach(type => {
        const currentType = currentCompanyData[type.key];
        const previousType = getHanaponBoxPreviousType(previousData, companyKey, type.key);
        if (!isHanaponBoxObject(currentType) || !isHanaponBoxObject(previousType)) return;

        const expectedCarry = calculateHanaponBoxEndBalance(previousType, previousYear, previousMonth);
        const currentCarry = parseInt(currentType.carryover, 10);
        if (Number.isNaN(currentCarry) || currentCarry !== expectedCarry) {
            currentType.carryover = expectedCarry;
            changed = true;
        }
    });

    if (changed && companyKey === HANAPON_BOX_LEGACY_COMPANY_KEY) {
        syncHanaponBoxLegacyMonth(currentData);
    }
    return changed;
}

function initHanaponBox() {
    const stored = localStorage.getItem(HANAPON_BOX_STORAGE_KEY);
    if (stored) {
        try {
            hanaponBoxAllData = normalizeHanaponBoxData(JSON.parse(stored));
        } catch (error) {
            hanaponBoxAllData = {};
        }
    } else {
        hanaponBoxAllData = {};
    }

    ensureHanaponBoxMonth(hanaponBoxCurrentYear, hanaponBoxCurrentMonth, false);
    localStorage.setItem(HANAPON_BOX_STORAGE_KEY, JSON.stringify(hanaponBoxAllData));
    scheduleDailyBackupRefresh();
    setupHanaponBoxMonthSelector();
    setupHanaponBoxCompanyTabs();

    if (database && window.SharedSync && !hanaponBoxDataSync) {
        hanaponBoxDataSync = SharedSync.createPathSync({
            database,
            path: HANAPON_BOX_DB_PATH,
            emptyValue: {},
            normalize: normalizeHanaponBoxData,
            mergeInitial: true,
            pendingStorageKey: HANAPON_BOX_STORAGE_KEY + '_pending_sync',
            serverSnapshotStorageKey: HANAPON_BOX_STORAGE_KEY + '_server_snapshot',
            getLocal: () => hanaponBoxAllData,
            setLocal: value => {
                hanaponBoxAllData = normalizeHanaponBoxData(value);
                ensureHanaponBoxMonth(hanaponBoxCurrentYear, hanaponBoxCurrentMonth, false);
                localStorage.setItem(HANAPON_BOX_STORAGE_KEY, JSON.stringify(hanaponBoxAllData));
                scheduleDailyBackupRefresh();
            },
            onRemote: () => {
                const activeEl = document.activeElement;
                ensureHanaponBoxMonth(hanaponBoxCurrentYear, hanaponBoxCurrentMonth, false);
                if (!activeEl?.closest('#hanapon-box-view-container')
                    && hanaponBoxViewContainer.style.display === 'block') {
                    renderHanaponBox();
                }
            }
        });
    }
}

function setupHanaponBoxCompanyTabs() {
    const buttons = document.querySelectorAll('#hanaponBoxCompanyTabs [data-company]');
    if (!buttons.length) return;

    buttons.forEach(button => {
        button.addEventListener('click', () => {
            const companyKey = button.dataset.company;
            if (!HANAPON_BOX_COMPANIES.some(company => company.key === companyKey)) return;
            hanaponBoxActiveCompany = companyKey;
            buttons.forEach(item => {
                const isActive = item.dataset.company === hanaponBoxActiveCompany;
                item.classList.toggle('active', isActive);
                item.setAttribute('aria-selected', String(isActive));
            });
            renderHanaponBox();
        });
    });
}

function setupHanaponBoxMonthSelector() {
    const yearSelect = document.getElementById('yearSelectHanaponBox');
    const monthSelect = document.getElementById('monthSelectHanaponBox');
    const previousButton = document.getElementById('prevMonthHanaponBox');
    const nextButton = document.getElementById('nextMonthHanaponBox');
    if (!yearSelect || !monthSelect) return;

    yearSelect.innerHTML = '';
    for (let year = 2024; year <= 2100; year++) {
        const option = document.createElement('option');
        option.value = year;
        option.textContent = year;
        yearSelect.appendChild(option);
    }

    monthSelect.innerHTML = '';
    for (let month = 1; month <= 12; month++) {
        const option = document.createElement('option');
        option.value = month;
        option.textContent = month;
        monthSelect.appendChild(option);
    }

    yearSelect.value = hanaponBoxCurrentYear;
    monthSelect.value = hanaponBoxCurrentMonth;

    const update = () => {
        hanaponBoxCurrentYear = parseInt(yearSelect.value, 10);
        hanaponBoxCurrentMonth = parseInt(monthSelect.value, 10);
        ensureHanaponBoxMonth(hanaponBoxCurrentYear, hanaponBoxCurrentMonth);
        if (canWriteAppData()
            && refreshHanaponBoxMonthCarryover(hanaponBoxCurrentYear, hanaponBoxCurrentMonth, hanaponBoxActiveCompany)) {
            saveHanaponBoxData(false);
        }
        renderHanaponBox();
    };

    yearSelect.addEventListener('change', update);
    monthSelect.addEventListener('change', update);
    previousButton?.addEventListener('click', () => {
        let year = parseInt(yearSelect.value, 10);
        let month = parseInt(monthSelect.value, 10) - 1;
        if (month < 1) { month = 12; year--; }
        if (year < 2024) return;
        yearSelect.value = year;
        monthSelect.value = month;
        update();
    });
    nextButton?.addEventListener('click', () => {
        let year = parseInt(yearSelect.value, 10);
        let month = parseInt(monthSelect.value, 10) + 1;
        if (month > 12) { month = 1; year++; }
        if (year > 2100) return;
        yearSelect.value = year;
        monthSelect.value = month;
        update();
    });
}

function saveHanaponBoxData(triggerHistory = true) {
    if (!canWriteAppData()) return false;
    hanaponBoxAllData = normalizeHanaponBoxData(hanaponBoxAllData);
    localStorage.setItem(HANAPON_BOX_STORAGE_KEY, JSON.stringify(hanaponBoxAllData));
    scheduleDailyBackupRefresh();
    if (triggerHistory) triggerHistorySave();

    if (database && hanaponBoxDataSync && Object.keys(hanaponBoxAllData).length > 0) {
        hanaponBoxDataSync.save(hanaponBoxAllData);
        const status = document.getElementById('saveStatusHanaponBox');
        if (status) {
            status.textContent = '保存しました ' + new Date().toLocaleTimeString();
            setTimeout(() => { status.textContent = ''; }, 3000);
        }
    }
    return true;
}

function handleHanaponBoxInput(event) {
    const target = event.target;
    if (!target.classList.contains('hanapon-box-input')) return;

    const inputYear = hanaponBoxCurrentYear;
    const inputMonth = hanaponBoxCurrentMonth;
    const inputCompany = hanaponBoxActiveCompany;
    const key = `${inputYear}-${inputMonth}`;
    ensureHanaponBoxMonth(inputYear, inputMonth, false);
    const monthData = hanaponBoxAllData[key];
    const companyData = monthData?.[inputCompany];
    const typeData = companyData?.[target.dataset.type];
    if (!typeData) return;

    const parsed = target.value.trim() === '' ? 0 : parseInt(target.value, 10);
    if (Number.isNaN(parsed)) return;

    const field = target.dataset.field;
    if (field === 'carryover') {
        typeData.carryover = parsed;
    } else {
        const day = target.dataset.day;
        if (!field || !day) return;
        if (!typeData.days) typeData.days = {};
        if (!typeData.days[day]) typeData.days[day] = {};
        if (parsed === 0) {
            delete typeData.days[day][field];
            if (Object.keys(typeData.days[day]).length === 0) delete typeData.days[day];
        } else {
            typeData.days[day][field] = parsed;
        }
    }

    if (inputCompany === HANAPON_BOX_LEGACY_COMPANY_KEY) {
        syncHanaponBoxLegacyMonth(monthData);
    }

    // Preserve the edit locally and in SharedSync before waiting to calculate
    // future-month carryover values.
    localStorage.setItem(HANAPON_BOX_STORAGE_KEY, JSON.stringify(hanaponBoxAllData));
    scheduleDailyBackupRefresh();
    triggerHistorySave();
    if (hanaponBoxDataSync) hanaponBoxDataSync.save(hanaponBoxAllData);

    hanaponBoxPendingSaveContext = {
        year: inputYear,
        month: inputMonth,
        company: inputCompany
    };
    clearTimeout(hanaponBoxSaveTimer);
    hanaponBoxSaveTimer = setTimeout(flushHanaponBoxPendingSave, 500);
}

function flushHanaponBoxPendingSave() {
    const context = hanaponBoxPendingSaveContext;
    if (!context) return;

    clearTimeout(hanaponBoxSaveTimer);
    hanaponBoxSaveTimer = null;
    hanaponBoxPendingSaveContext = null;
    propagateHanaponBoxCarryover(context.year, context.month, context.company);
    saveHanaponBoxData();
    if (hanaponBoxDataSync) hanaponBoxDataSync.flush();
}

function renderHanaponBox() {
    ensureHanaponBoxMonth(hanaponBoxCurrentYear, hanaponBoxCurrentMonth, false);
    const key = `${hanaponBoxCurrentYear}-${hanaponBoxCurrentMonth}`;
    const monthData = hanaponBoxAllData[key];
    const companyData = monthData?.[hanaponBoxActiveCompany]
        || monthData?.[HANAPON_BOX_LEGACY_COMPANY_KEY];
    const head = document.getElementById('hanaponBoxHead');
    const body = document.getElementById('hanaponBoxBody');
    const foot = document.getElementById('hanaponBoxFoot');
    if (!monthData || !companyData || !head || !body || !foot) return;
    document.querySelectorAll('#hanaponBoxCompanyTabs [data-company]').forEach(button => {
        const isActive = button.dataset.company === hanaponBoxActiveCompany;
        button.classList.toggle('active', isActive);
        button.setAttribute('aria-selected', String(isActive));
    });

    let mainHeader = '<tr class="header-main-stock"><th rowspan="2" class="date-col-stock">日付</th>';
    let subHeader = '<tr class="header-sub-stock">';
    HANAPON_BOX_TYPES.forEach(type => {
        mainHeader += `<th colspan="3" class="group-film-stock" style="background: ${type.bg}; color: ${type.color}; border: 1px solid var(--border);">${type.name}</th>`;
        subHeader += '<th class="sub-film-stock">入荷</th>';
        subHeader += '<th class="sub-film-stock">使用数</th><th class="sub-film-stock remaining-stock">残数</th>';
    });
    head.innerHTML = mainHeader + '</tr>' + subHeader + '</tr>';

    let carryRow = '<tr class="carryover-row" style="background: rgba(var(--primary-rgb), 0.05);"><td style="font-weight:700; padding:0.5rem; white-space:nowrap; border:1px solid var(--border);"><span class="carryover-text-desktop">前月繰越</span><span class="carryover-text-mobile">繰越</span></td>';
    HANAPON_BOX_TYPES.forEach(type => {
        const typeData = companyData[type.key] || { carryover: 0, days: {} };
        const carry = parseInt(typeData.carryover, 10) || 0;
        carryRow += '<td style="border:1px solid var(--border);"></td>';
        carryRow += '<td style="border:1px solid var(--border);"></td>';
        carryRow += `<td class="remaining-stock" style="border:1px solid var(--border);"><input type="number" min="0" class="hanapon-box-input carry-input" data-type="${type.key}" data-field="carryover" value="${carry}" style="width:90%; background:transparent; border:none; font-weight:800; color:var(--primary); text-align:center; padding:2px;"></td>`;
    });
    carryRow += '</tr>';

    const daysInMonth = new Date(hanaponBoxCurrentYear, hanaponBoxCurrentMonth, 0).getDate();
    const weekdayLabels = ['日', '月', '火', '水', '木', '金', '土'];
    const todayStr = currentDate;
    let rows = '';

    for (let day = 1; day <= daysInMonth; day++) {
        const dateObj = new Date(hanaponBoxCurrentYear, hanaponBoxCurrentMonth - 1, day);
        const dateStr = `${hanaponBoxCurrentYear}-${String(hanaponBoxCurrentMonth).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        const isHoliday = isRollHoliday(hanaponBoxCurrentYear, hanaponBoxCurrentMonth, day);
        const isToday = dateStr === todayStr;
        let rowClass = '';
        if (isToday) rowClass = 'sliver-row-today';
        else if (isHoliday) rowClass = 'weekend-holiday';
        else if (dateObj.getDay() === 0) rowClass = 'weekend-sun';
        else if (dateObj.getDay() === 6) rowClass = 'weekend-sat';

        rows += `<tr class="${rowClass}"><td class="date-cell" style="border:1px solid var(--border);"><div class="date-desktop">${hanaponBoxCurrentMonth}/${day}(${weekdayLabels[dateObj.getDay()]})</div><div class="date-mobile"><div class="date-num">${day}</div><div class="day-name">${weekdayLabels[dateObj.getDay()]}</div></div></td>`;
        HANAPON_BOX_TYPES.forEach(type => {
            const typeData = companyData[type.key] || { carryover: 0, days: {} };
            const dayData = typeData.days?.[day] || {};
            const incoming = dayData.incoming || '';
            const usage = dayData.usage || '';
            const balance = calculateHanaponBoxEndBalance(typeData, hanaponBoxCurrentYear, hanaponBoxCurrentMonth, day);
            rows += `<td style="border:1px solid var(--border); padding:0.25rem;"><input type="number" min="0" class="hanapon-box-input stock-input" data-type="${type.key}" data-field="incoming" data-day="${day}" value="${incoming}" style="width:100%; border:none; padding:4px; text-align:center;"></td>`;
            rows += `<td style="border:1px solid var(--border); padding:0.25rem;"><input type="number" min="0" class="hanapon-box-input stock-input" data-type="${type.key}" data-field="usage" data-day="${day}" value="${usage}" style="width:100%; border:none; padding:4px; text-align:center;"></td>`;
            rows += `<td class="remaining-stock ${balance < STOCK_LOW_THRESHOLD ? 'low-stock' : ''}" style="border:1px solid var(--border);">${balance}</td>`;
        });
        rows += '</tr>';
    }
    body.innerHTML = carryRow + rows;

    let footer = '<tr><td style="font-weight:700; border:1px solid var(--border); text-align:center;">月末残</td>';
    HANAPON_BOX_TYPES.forEach(type => {
        const typeData = companyData[type.key] || { carryover: 0, days: {} };
        const balance = calculateHanaponBoxEndBalance(typeData, hanaponBoxCurrentYear, hanaponBoxCurrentMonth);
        footer += `<td style="border:1px solid var(--border);"></td><td style="border:1px solid var(--border);"></td><td class="remaining-stock" style="font-weight:800; border:1px solid var(--border); background:rgba(var(--primary-rgb), 0.05);">${balance}</td>`;
    });
    foot.innerHTML = footer + '</tr>';

    body.querySelectorAll('.hanapon-box-input').forEach(input => {
        input.addEventListener('input', handleHanaponBoxInput);
        input.addEventListener('change', renderHanaponBox);
        input.addEventListener('blur', flushHanaponBoxPendingSave);
    });
}

function propagateHanaponBoxCarryover(year, month, companyKey = hanaponBoxActiveCompany) {
    if (!HANAPON_BOX_COMPANIES.some(company => company.key === companyKey)) {
        companyKey = HANAPON_BOX_LEGACY_COMPANY_KEY;
    }

    let currentYear = parseInt(year, 10);
    let currentMonth = parseInt(month, 10);
    let changed = false;

    for (let index = 0; index < 24; index++) {
        const currentKey = `${currentYear}-${currentMonth}`;
        const currentData = hanaponBoxAllData[currentKey];
        const currentCompanyData = currentData?.[companyKey];
        if (!isHanaponBoxObject(currentData) || !isHanaponBoxObject(currentCompanyData)) break;

        let nextMonth = currentMonth + 1;
        let nextYear = currentYear;
        if (nextMonth > 12) { nextMonth = 1; nextYear++; }
        const nextKey = `${nextYear}-${nextMonth}`;
        const nextData = hanaponBoxAllData[nextKey];
        const nextCompanyData = nextData?.[companyKey];
        if (!isHanaponBoxObject(nextData) || !isHanaponBoxObject(nextCompanyData)) break;

        HANAPON_BOX_TYPES.forEach(type => {
            const currentType = currentCompanyData[type.key];
            const nextType = nextCompanyData[type.key];
            if (!currentType || !nextType) return;
            const nextCarry = calculateHanaponBoxEndBalance(currentType, currentYear, currentMonth);
            if (nextType.carryover !== nextCarry) {
                nextType.carryover = nextCarry;
                changed = true;
            }
        });

        if (companyKey === HANAPON_BOX_LEGACY_COMPANY_KEY) {
            syncHanaponBoxLegacyMonth(currentData);
            syncHanaponBoxLegacyMonth(nextData);
        }

        currentYear = nextYear;
        currentMonth = nextMonth;
    }

    if (changed) {
        saveHanaponBoxData(false);
    }
}

